def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    return sorted(divs)

def verify_solution(n):
    divisors = get_divisors(n)
    num_divisors = len(divisors)

    if num_divisors < 5:
        return f"FAIL: Not enough divisors ({num_divisors})."

    # Divisors are 1-indexed: d_1=1, d_2=a, d_3=b, d_5=c
    try:
        a = divisors[1]  # Second smallest
        b = divisors[2]  # Third smallest
        c = divisors[4]  # Fifth smallest
    except IndexError:
        # Should not happen if num_divisors >= 5
        return "FAIL: Could not identify a, b, or c due to unexpected divisor count."

    # Check the structural relationship: n = ab + ac + bc
    required_n = a*b + a*c + b*c

    is_satisfied = (required_n == n)

    status = "SUCCESS" if is_satisfied else "FAILURE"

    return f"N={n}: Status={status}. Divisors: {divisors}. a={a}, b={b}, c={c}. Calculated N = {required_n}. Check: {is_satisfied}"

solutions_to_check = [36, 56, 135, 231, 351, 455, 663, 935]
results = []
for n in solutions_to_check:
    results.append(verify_solution(n))

for result in results:
    print(result)

